def show_gpa_page():
    main_frame.pack_forget()
    gpa_frame.pack(fill="both", expand=True)

def show_main_page():
    gpa_frame.pack_forget()
    labs_frame.pack_forget()
    main_frame.pack(fill="both", expand=True)

def show_labs_page():
    main_frame.pack_forget()
    labs_frame.pack(fill="both", expand=True)

def toggle_gpa_fields():
    if has_gpa_var.get() == 1:
        privious_gpa.config(state = "normal")
        privious_hours.config(state = "normal")
    else:
        privious_gpa.config(state = "disabled")
        privious_hours.config(state = "disabled")

def open_lab_video():
    selected_lab = lab_combobox.get()
    if selected_lab in labs_info:
        video_url = labs_info[selected_lab].get("video", "")
        if video_url:
            webbrowser.open(video_url)
        else:
            messagebox.showinfo("No Video", "No video is available for this lab yet.", parent=labs_frame)

def display_lab_info(event=None):
    selected_lab = lab_combobox.get()

    if selected_lab in labs_info:
        info = labs_info[selected_lab]

        details_text = f"Building: {info['building']}\nFloor: {info['floor']}\nDirection: {info['direction']}"
        lab_details_label.config(text=details_text)

        image_key = info['image']

        try:
            b64_data = IMAGES_B64[image_key]
            img_bytes = base64.b64decode(b64_data)
            pil_image = Image.open(io.BytesIO(img_bytes))
            pil_image.thumbnail((800, 600))

            img = ImageTk.PhotoImage(pil_image)

            lab_image_label.config(image=img)
            lab_image_label.image = img

        except Exception as e:
            lab_image_label.config(image="")
            messagebox.showerror("Error", f"Could not open image:\n{e}", parent=labs_frame)

        if info.get("video", ""):
            video_button.config(state="normal")
        else:
            video_button.config(state="disabled")

def subject_data():
    try:
        sn = int(nof.get())
    except ValueError:
        messagebox.showwarning("Error", "Please enter a valid number!",parent=gpa_frame)
        return

    grades_boxes.clear()
    hours_boxes.clear()

    for W in subjects_frame.winfo_children():
        W.destroy()

    tk.Label(subjects_frame, text="Grade", font=("Arial", 12, "bold")).grid(row=0, column=0, pady=5)
    tk.Label(subjects_frame, text="Credit Hour", font=("Arial", 12, "bold")).grid(row=0, column=1, pady=5)

    for i in range(sn):
        grades_menu = ttk.Combobox(subjects_frame, values=["A+","A","A-","B+","B","B-","C+","C","C-","D+","D","D-"], font=("Arial", 11), width=10)
        hours_menu = ttk.Combobox(subjects_frame, values=["3","2","1"], font=("Arial", 11), width=8)

        grades_menu.grid(row=i+1, column=0, pady=2, padx=5)
        hours_menu.grid(row=i+1, column=1, pady=2, padx=5)

        grades_boxes.append(grades_menu)
        hours_boxes.append(hours_menu)




def CG():
    total_hours = 0
    total_points = 0.0
    for j in range(len(grades_boxes)):
        g = grades_boxes[j].get()

        try:
            h = int(hours_boxes[j].get())
            point = grade_points[g]
        except ValueError:
            messagebox.showwarning("Error", "Please select credit hours for all subjects!", parent=gpa_frame)
            return
        except KeyError:
            messagebox.showwarning("Error", "Please select a grade for all subjects!", parent=gpa_frame)
            return

        total_hours += h
        total_points += (point * h)

    if total_hours == 0:
        messagebox.showwarning("Error", "Please enter a valid number!",parent=gpa_frame)
        return

    semester_gpa = total_points / total_hours
    messagesg.config(text=f"- Semester GPA : ( {semester_gpa:.2f} )  ^_^")

    if has_gpa_var.get() == 1:
        try:
            p_gpa = float(privious_gpa.get())
            p_hours = int(privious_hours.get())
        except ValueError:
            messagebox.showwarning("Error", "Please enter valid numbers for Previous GPA and Hours!", parent=gpa_frame)
            return

        p_points = p_gpa * p_hours
        cumulative_points = p_points + total_points
        cumulative_hours = p_hours + total_hours
        cumulative_gpa = cumulative_points / cumulative_hours
        messagecg.config(text=f"- Cumulative GPA : ( {cumulative_gpa:.2f} ) :)")



def clear_data():
    has_gpa_var.set(0)

    privious_gpa.config(state="normal")
    privious_gpa.delete(0, tk.END)
    privious_gpa.config(state="disabled")

    privious_hours.config(state="normal")
    privious_hours.delete(0, tk.END)
    privious_hours.config(state="disabled")

    nof.delete(0, tk.END)

    grades_boxes.clear()
    hours_boxes.clear()
    for widget in subjects_frame.winfo_children():
        widget.destroy()

    messagesg.config(text="")
    messagecg.config(text="")




